-- OTOTR Finance migration promoted from a reviewed candidate.
-- Source: candidate-contract-version-approve-rpc.sql
-- Source SHA256: CEB0ADE6CC9F0173CBED4C88E5E70E306E61FA14E9E1FCD85EA5989E2C30126F
-- Local replay required before any staging promotion.
-- OTOTR CONTRACT VERSION APPROVE RPC CANDIDATE
create or replace function finance_private.current_contract_version_approve_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_contract_version_approve_scope(p_actor_id uuid,p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_contract_version_approve(p_contract_version_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.contract-versions.approve' then null::jsonb else finance_private.resolve_contract_version_approve_scope(auth.uid(),p_contract_version_id,p_permission) end$$;
create or replace function finance_api.commit_contract_version_approve(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_version_id uuid,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare v record;ar finance.approval_requests%rowtype;ast finance.approval_steps%rowtype;v_existing record;v_new bigint;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_contract_version_approve_committer_is_trusted() then raise exception using errcode='42501',message='trusted contract version approve committer required';end if;
 if p_expected_version<1 or (p_reason_code is not null and pg_catalog.length(pg_catalog.btrim(p_reason_code)) not between 1 and 100) or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid contract version approve command';end if;
 select cv.*,fc.legal_entity_id,fc.dealer_legal_entity_id,fc.status contract_status into v from finance.contract_versions cv join finance.franchise_contracts fc on fc.id=cv.contract_id where cv.id=p_contract_version_id for update of cv,fc;if not found then raise exception using errcode='P0002',message='contract version not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=v.legal_entity_id and om.event_type='CONTRACT_VERSION_APPROVED' and om.aggregate_id=v.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','versionId',v.id,'status','APPROVED','version',(v_existing.payload->>'version')::bigint,'approvalRequestId',v_existing.payload->>'approvalRequestId');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if v.legal_entity_id<>p_legal_entity_id or v.dealer_legal_entity_id<>p_dealer_legal_entity_id or v.contract_status in ('TERMINATED','DISCARDED') or v.status<>'PENDING_APPROVAL' or v.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if v.prepared_by=p_actor_id then raise exception using errcode='42501',message='maker checker violation';end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract version approve three dimensional scope denied';end if;
 select * into ar from finance.approval_requests x where x.legal_entity_id=p_legal_entity_id and x.subject_type='CONTRACT_VERSION' and x.subject_id=v.id and x.status='PENDING' for update;if not found or ar.prepared_by<>v.prepared_by then raise exception using errcode='23514',message='pending approval request required';end if;
 select * into ast from finance.approval_steps s where s.approval_request_id=ar.id and s.step_no=1 and s.required_role='finance-approver' for update;if not found or ast.decision is not null then raise exception using errcode='23514',message='pending finance approver step required';end if;
 if not exists(select 1 from finance.contract_fee_rules r where r.contract_version_id=v.id) or exists(select 1 from finance.contract_fee_rules r where r.contract_version_id=v.id and (r.status<>'PENDING_APPROVAL' or r.configuration_status<>'CONFIGURED' or r.prepared_by<>v.prepared_by)) then raise exception using errcode='23514',message='pending configured fee rules required for approval';end if;
 if exists(select 1 from finance.rule_exceptions e join finance.contract_fee_rules r on r.id=e.contract_fee_rule_id where r.contract_version_id=v.id and e.status not in ('DISABLED','SUPERSEDED')) then raise exception using errcode='0A000',message='rule exception precedence decision pending';end if;
 update finance.approval_steps set decision='APPROVE',decided_by=p_actor_id,decided_at_utc=pg_catalog.statement_timestamp(),evidence_ref='APPROVAL_EVENT:'||p_correlation_id::text where id=ast.id;
 update finance.approval_requests set status='APPROVED',version=version+1,correlation_id=p_correlation_id where id=ar.id;
 update finance.contract_fee_rules set status='APPROVED',approved_by=p_actor_id,approved_at_utc=pg_catalog.statement_timestamp(),version=version+1,correlation_id=p_correlation_id where contract_version_id=v.id and status='PENDING_APPROVAL' and configuration_status='CONFIGURED';
 v_new:=v.version+1;update finance.contract_versions set status='APPROVED',approved_by=p_actor_id,approved_at_utc=pg_catalog.statement_timestamp(),version=v_new,correlation_id=p_correlation_id where id=v.id;
 v_payload:=pg_catalog.jsonb_build_object('versionId',v.id,'contractId',v.contract_id,'approvalRequestId',ar.id,'dealerLegalEntityId',v.dealer_legal_entity_id,'branchId',p_branch_id,'contentHash',v.content_hash,'version',v_new,'reasonCode',p_reason_code,'noteHash',p_note_hash,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','CONTRACT_VERSION_APPROVED','CONTRACT_VERSION',v.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||v.id::text||':CONTRACT_VERSION_APPROVED:'||v.content_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','CONTRACT_VERSION_APPROVED','CONTRACT_VERSION',v.id,'ALLOW',p_reason_code,v.content_hash,v.content_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('contractId',v.contract_id,'approvalRequestId',ar.id,'approvalStepId',ast.id,'branchId',p_branch_id,'preparedBy',v.prepared_by,'approverId',p_actor_id,'noteHash',p_note_hash,'previousVersion',v.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','APPROVED','versionId',v.id,'status','APPROVED','version',v_new,'approvalRequestId',ar.id);
end$$;
revoke all on function finance_private.current_contract_version_approve_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_contract_version_approve_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_contract_version_approve(uuid,text) from public,anon;grant execute on function finance_api.authorize_contract_version_approve(uuid,text) to authenticated;revoke all on function finance_api.commit_contract_version_approve(uuid,uuid,uuid,uuid,uuid,uuid,bigint,text,text,text,text,uuid) from public,anon,authenticated;
